#include "A.h"

#include <stdio.h>
#include <string.h>



bool A_LoadAll(A_t* data, const char* base_path,
                                  char* error, size_t error_size)
{
    char path[1024];

    memset(data, 0, sizeof *data);


    if (snprintf(path, sizeof path, "%s/%s.table",
                 base_path, "Template") >= (int)sizeof path) {
        sm_copy_error(error, error_size, base_path, "the path to a table file is too long");
        A_Free(data);
        return false;
    }

    if (!A_TemplateLoad(&data->template_, path, error, error_size)) {
        /* Everything loaded so far goes too. A model missing one table is not one
         * a caller can use, and leaving it allocated makes that a leak as well. */
        A_Free(data);
        return false;
    }



    return true;
}

void A_Free(A_t* data)
{
    A_TemplateFree(&data->template_);
}
